/* global window, getComputedStyle, document, innerWidth, innerHeight -- inspectTargetElement runs in the browser through the fixed MCP evaluation. */
// Read-only grounding for native computer input. Never dispatch a DOM action.
// Keep prompts general. Only give interaction advice that applies across common tasks; keep case-specific steps in tests.
export const browserTargetTool = {
  name: "browser_inspect_target",
  description:
    "Inspect a current top-level accessibility ref from browser_snapshot or browser_find. Returns visible native-computer coordinates that currently hit that element, or why none were found, plus actual keyboard focus. Use before clicking a small, overlapping or uncertain control, or to verify focus after native Tab navigation. focused is true only when this exact element has focus, not a child control. The role, label and ariaLabelledBy fields are literal DOM attributes. Use accessibleName only when accessibleNameState is observed. Unverified means the tool did not establish the name. This does not click, scroll, focus or authorize an action. Coordinates and focus can change; inspect again after changes. Frame refs are not supported.",
  inputSchema: {
    type: "object",
    properties: {
      ref: {
        type: "string",
        description: "Current top-level snapshot ref, such as e42.",
      },
    },
    required: ["ref"],
    additionalProperties: false,
  },
  annotations: { readOnlyHint: true },
};

export function inspectTargetElement(element, includeNameCandidate = false) {
  if (window !== window.top)
    return { status: "frame-not-supported", point: null };
  const describe = (node) =>
    node
      ? {
          tag: node.tagName.toLowerCase(),
          role: node.getAttribute("role"),
          label: node.getAttribute("aria-label"),
          text: node.matches('button, a, [role="button"], [role="link"]')
            ? node.innerText?.trim()
            : undefined,
        }
      : null;
  const r = element.getBoundingClientRect();
  const bounds = { x: r.x, y: r.y, width: r.width, height: r.height };
  let active = document.activeElement;
  while (active?.shadowRoot?.activeElement)
    active = active.shadowRoot.activeElement;
  const base = {
    nameCandidate: includeNameCandidate
      ? (
          element.ariaLabelledByElements
            ?.map((label) => label.innerText)
            .join(" ") ||
          element.getAttribute("aria-label") ||
          ""
        )
          .replace(/\s+/g, " ")
          .trim()
      : undefined,
    element: {
      ...describe(element),
      ariaLabelledBy: element.getAttribute("aria-labelledby"),
      accessibleNameState: "unverified",
    },
    bounds,
    keyboard: {
      focused: active === element,
      tabIndex: element.tabIndex,
      activeElement: describe(active),
    },
  };
  let ancestor = element;
  while (ancestor) {
    const style = getComputedStyle(ancestor);
    if (
      style.visibility !== "visible" ||
      style.display === "none" ||
      Number(style.opacity) === 0
    )
      return { ...base, status: "not-visible", point: null };
    ancestor = ancestor.parentElement ?? ancestor.getRootNode()?.host;
  }
  const disabled =
    element.matches(":disabled") ||
    element.getAttribute("aria-disabled") === "true";
  const hit = (x, y) => {
    let node = document.elementFromPoint(x, y);
    while (node?.shadowRoot) {
      const inner = node.shadowRoot.elementFromPoint(x, y);
      if (!inner || inner === node) break;
      node = inner;
    }
    let current = node;
    while (current && current !== element)
      current = current.parentElement ?? current.getRootNode()?.host;
    return { matches: current === element, node };
  };
  const center = { x: r.x + r.width / 2, y: r.y + r.height / 2 };
  const centerHit = hit(center.x, center.y);
  const ancestors = [];
  for (
    let parent = centerHit.node?.parentElement;
    parent;
    parent = parent.parentElement
  ) {
    if (parent.getAttribute("aria-label") || parent.getAttribute("role"))
      ancestors.push(describe(parent));
  }
  const centerObservation = {
    ...center,
    hitsTarget: centerHit.matches,
    receiver: describe(centerHit.node),
    ancestors,
  };
  for (const rect of element.getClientRects()) {
    const left = Math.max(rect.left, 0),
      top = Math.max(rect.top, 0);
    const right = Math.min(rect.right, innerWidth),
      bottom = Math.min(rect.bottom, innerHeight);
    if (right <= left || bottom <= top) continue;
    for (const fx of [0.5, 0.25, 0.75, 0.1, 0.9]) {
      for (const fy of [0.5, 0.25, 0.75, 0.1, 0.9]) {
        const x = left + (right - left) * fx,
          y = top + (bottom - top) * fy;
        if (hit(x, y).matches)
          return {
            ...base,
            status: disabled ? "disabled" : "available",
            point: { x, y },
            center: centerObservation,
          };
      }
    }
  }
  return {
    ...base,
    status: disabled ? "disabled" : "no-visible-point-found",
    point: null,
    center: centerObservation,
  };
}

function snapshotElement(result, ref) {
  if (!result || result.isError) return;
  const text = result.content?.find((block) => block.type === "text")?.text;
  const sections = text?.matchAll(/^### Snapshot\n```yaml\n([\s\S]*?)\n```$/gm);
  const snapshots = [...(sections ?? [])];
  if (snapshots.length !== 1) return;
  for (const line of snapshots[0][1].split("\n")) {
    const row = /^( *)- (.*)$/.exec(line);
    if (!row) continue;
    // Playwright single-quotes a snapshot key when its JSON-quoted name
    // contains YAML syntax. Read the key separately from any inline text.
    const quoted = /^'((?:[^']|'')*)'(?::(?: .*)?)?$/.exec(row[2]);
    const key = quoted ? quoted[1].replaceAll("''", "'") : row[2];
    const node =
      /^([a-z][a-z0-9-]*)(?: ("(?:[^"\\]|\\.)*"))?((?: \[[\w=,.-]+\])+)(?::(?: .*)?)?$/.exec(
        key,
      );
    if (node?.[3].match(/ \[ref=((?:f\d+)?e\d+)\]/)?.[1] !== ref) continue;
    return {
      depth: row[1].length / 2,
      role: node[1],
      name: node[2] && JSON.parse(node[2]),
    };
  }
}

async function confirmName(mcp, ref, role, name, signal) {
  // Pin the exact role/name matcher to the existing ref. A matching name on
  // another element cannot confirm it. Evaluation preserves the snapshot refs.
  const roleSelector = `internal:role=${role}[name=${JSON.stringify(name)}s]`;
  const target = `aria-ref=${ref} >> internal:and=${JSON.stringify(roleSelector)}`;
  const result = await mcp.callToolResult(
    "browser_evaluate",
    {
      target,
      function: "(element) => element.isConnected && window === window.top",
    },
    undefined,
    { signal },
  );
  if (
    !result.isError &&
    result.content?.[0]?.text?.split("\n", 2).join("\n") === "### Result\ntrue"
  )
    return name;
}

export async function inspectBrowserTarget(
  mcp,
  ref,
  { signal, page, previousSnapshot, validate } = {},
) {
  if (typeof ref !== "string" || !/^(?:f\d+)?e\d+$/.test(ref))
    throw new Error(
      "Use a current snapshot ref. Nested frames are not supported.",
    );
  // Depth and box options change what is rendered, but preserve page scope.
  const observed =
    previousSnapshot?.name === "browser_snapshot" &&
    previousSnapshot.status === "returned" &&
    previousSnapshot.arguments.target === undefined &&
    previousSnapshot.arguments.filename === undefined
      ? snapshotElement(previousSnapshot.output, ref)
      : undefined;
  const depth = observed?.name ? undefined : observed?.depth;
  const readName = page && Number.isInteger(depth);
  let navigated = false;
  const trackNavigation = (frame) => {
    if (frame === page.mainFrame()) navigated = true;
  };
  if (readName) page.on("framenavigated", trackNavigation);
  try {
    // Resolve in the same connection that produced the reference. Only this
    // fixed observational function is sent.
    const result = await mcp.callToolResult(
      "browser_evaluate",
      {
        target: ref,
        element: "selected target",
        function:
          readName && depth === 0
            ? `(element) => (${inspectTargetElement.toString()})(element, true)`
            : inspectTargetElement.toString(),
      },
      undefined,
      { signal },
    );
    if (result.isError) return result;
    const text = result.content
      ?.filter((block) => block.type === "text")
      .map((block) => block.text)
      .join("\n");
    if (!text?.startsWith("### Result\n"))
      throw new Error("Unexpected target inspection response");
    const { nameCandidate, ...value } = JSON.parse(
      text.slice("### Result\n".length).split("\n### ")[0],
    );
    if (readName && !navigated && !page.isClosed() && value.element) {
      validate?.();
      let name;
      if (depth > 0) {
        // A shallow full-page snapshot preserves the ref set.
        const snapshot = await mcp
          .callToolResult("browser_snapshot", { depth }, undefined, { signal })
          .catch(() => signal?.throwIfAborted());
        name = snapshotElement(snapshot, ref)?.name;
      } else if (nameCandidate) {
        // A depth of zero leaves the compact tree unchanged. Verify the label
        // text with Playwright's exact role/name matcher on the inspected ref.
        name = await confirmName(
          mcp,
          ref,
          observed.role,
          nameCandidate,
          signal,
        ).catch(() => signal?.throwIfAborted());
      }
      if (name && !navigated && !page.isClosed()) {
        validate?.();
        value.element.accessibleName = name;
        value.element.accessibleNameState = "observed";
      }
    }
    return {
      content: [{ type: "text", text: JSON.stringify({ ref, ...value }) }],
    };
  } finally {
    if (readName) page.off("framenavigated", trackNavigation);
  }
}
